struct Shape {
    kind: Str,
    params: Vec<Int>,
}

impl Shape {
    fn new_square(side: Int) -> Self {
        Shape { kind: "square".to_string(), params: vec![side] }
    }

    fn new_circle(radius: Float) -> Self {
        Shape { kind: "circle".to_string(), params: vec![radius] }
    }

    fn area(&self) -> Option<Float> {
        match self.kind.as_str() {
            "square" => Some(self.params[0].to_float() * self.params[0].to_float()),
            "circle" => Some(std::f64::consts::PI * self.params[0].to_float() * self.params[0].to_float()),
            _ => None,
        }
    }
}

fn main() {
    let shape = Shape::new_square(4);
    match shape.area() {
        Some(area) => print(area),
        None => println!("Invalid shape"),
    }
}

